// ENGLISH LEVELS (CEFR) + NATIVE SPEAKING MODES
// ═══════════════════════════════════════════════
function enLevelOf(card) { return (card && (card.lvl || EN_LEVELS[card.en])) || 'B2'; }
function enLevelBadge(lvl) {
  const c = { B1:'#94a3b8', B2:'#4cc9f0', C1:'#a855f7', C2:'#ff1744' }[lvl] || '#4cc9f0';
  return `<span style="display:inline-block;margin-left:.4rem;padding:.12rem .45rem;border-radius:6px;font-size:.62rem;font-weight:800;letter-spacing:.05em;background:${c}22;color:${c};border:1px solid ${c}88;vertical-align:middle">${lvl}</span>`;
}
function enExtrasHTML(card) {
  if(!card) return '';
  let h = '';
  if(card.c1) h += `<div style="margin-top:.6rem;font-size:.78rem;color:#c4b5fd">⬆️ C1 : ${card.c1}</div>`;
  if(card.c2) h += `<div style="margin-top:.3rem;font-size:.78rem;color:#fda4af">⬆️⬆️ C2 : ${card.c2}</div>`;
  const ex = card.say || (typeof PRON_DATA !== 'undefined' && PRON_DATA[card.en] ? PRON_DATA[card.en][0] : '');
  if(ex) h += `<div style="margin-top:.35rem;font-size:.78rem;color:#7dd3fc;font-style:italic">🗣️ « ${ex} »</div>`;
  return h;
}
/* Voix pré-enregistrées (audio/<lang>/<id>.mp3, index dans audio/manifest.js).
   Si le texte n'a pas d'enregistrement ou si la lecture échoue (hors ligne), on retombe sur la voix du téléphone. */
let _recAudio = null;
function playRecorded(lang, text, rate, fallback) {
  try {
    const m = (typeof AUDIO_MAP !== 'undefined' && AUDIO_MAP[lang]) || null; if(!m || !text) return false;
    const id = m[String(text).replace(/\(.*?\)/g, '').trim()]; if(!id) return false;
    try { speechSynthesis.cancel(); } catch(e) {}
    const old = _recAudio;
    const a = new Audio('audio/' + lang + '/' + id + '.mp3'); _recAudio = a;
    if(old) { try { old.pause(); } catch(e) {} }
    if(rate) a.playbackRate = Math.min(1.5, Math.max(.5, rate / 0.95));
    let failed = false;
    // un enregistrement interrompu par le suivant ne doit pas déclencher la voix de secours
    const fb = () => { if(failed || _recAudio !== a) return; failed = true; _recAudio = null; fallback(); };
    a.onerror = fb;
    const p = a.play(); if(p && p.catch) p.catch(fb);
    return true;
  } catch(e) { return false; }
}
function speakEN(text, rate, noRec) {
  try {
    if(!noRec && playRecorded('en', text, rate, () => speakEN(text, rate, true))) return;
    if(_recAudio) { const old = _recAudio; _recAudio = null; try { old.pause(); } catch(e) {} }
    if(!('speechSynthesis' in window) || !text) return;
    speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text.replace(/\(.*?\)/g,''));
    u.lang = 'en-US'; u.rate = rate || 0.95;
    const v = speechSynthesis.getVoices().find(v => v.lang === 'en-US');
    if(v) u.voice = v;
    speechSynthesis.speak(u);
  } catch(e) {}
}

